const mod = await import('qr-scanner');
const QRScanner = mod.default || mod;
globalThis.QRScanner = QRScanner;
const { readFileSync } = await import('node:fs');
const filePath = process.env.FILE_PATH;
if (!filePath) { throw new Error('Missing FILE_PATH env var'); }
try { readFileSync(filePath); } catch (e) { throw new Error('Input file not found'); }
globalThis.inputPath = filePath;

const { readFileSync } = await import('node:fs');
const data = readFileSync(globalThis.inputPath);
const blob = new Blob([data]);
globalThis.qrResult = await globalThis.QRScanner.scanImage(blob);
